const boardEl=document.querySelector('#board');
const teams={olympus:{name:'Les Olympiens',emblem:'☼',className:'olympus'},asgard:{name:'Les Asgardiens',emblem:'ᛟ',className:'asgard'}};
const specs={
  pawn:{title:'Demi-dieu',glyph:'⚔',hp:3,skill:'Élan héroïque',description:'Avancez de deux cases libres en un seul élan.'},
  rook:{title:'Tour · Dieu gardien',glyph:'🏛',hp:7,skill:'Bastion',description:'Restaurez 2 PV à un allié adjacent.'},
  knight:{title:'Cavalier · Dieu guerrier',glyph:'♞',hp:5,skill:'Foudre divine',description:'Frappez un ennemi à portée de 2 cases pour 3 dégâts.'},
  bishop:{title:'Fou · Dieu visionnaire',glyph:'🔱',hp:5,skill:'Oracle',description:'Restaurez 2 PV à un allié sur une diagonale dégagée.'},
  queen:{title:'Reine · Déesse suprême',glyph:'♛',hp:8,skill:'Colère céleste',description:'Infligez 3 dégâts à un ennemi visible en ligne droite.'},
  king:{title:'Roi · Père des dieux',glyph:'♚',hp:10,skill:'Égide',description:'Restaurez 3 PV à un allié adjacent, ou à vous-même.'}
};
const names={
  olympus:{pawn:['Persée','Héraclès','Achille','Atalante','Thésée','Jason','Orphée','Énée'],rook:['Héra','Héphaïstos'],knight:['Arès','Hermès'],bishop:['Apollon','Artémis'],queen:['Athéna'],king:['Zeus']},
  asgard:{pawn:['Sigurd','Brynhild','Beowulf','Ragnar','Sif','Leif','Gudrun','Skadi'],rook:['Heimdall','Tyr'],knight:['Thor','Freya'],bishop:['Frigg','Baldr'],queen:['Hel'],king:['Odin']}
};
let grid=[],turn='olympus',selected=null,legal=[],skillMode=false,round=1,history=[],gameOver=false,lastMove=null,toastTimer;
function makePiece(type,team,name){return{id:`${team}-${type}-${name}`,type,team,name,hp:specs[type].hp,maxHp:specs[type].hp,used:false}}
function setup(){grid=Array.from({length:8},()=>Array(8).fill(null));for(const team of ['asgard','olympus']){const back=team==='asgard'?0:7,pawns=team==='asgard'?1:6;const row=['rook','knight','bishop','queen','king','bishop','knight','rook'];row.forEach((type,c)=>grid[back][c]=makePiece(type,team,names[team][type].shift()));for(let c=0;c<8;c++)grid[pawns][c]=makePiece('pawn',team,names[team].pawn.shift())}
// Restore name lists after consuming them for setup.
  names.olympus={pawn:['Persée','Héraclès','Achille','Atalante','Thésée','Jason','Orphée','Énée'],rook:['Héra','Héphaïstos'],knight:['Arès','Hermès'],bishop:['Apollon','Artémis'],queen:['Athéna'],king:['Zeus']};names.asgard={pawn:['Sigurd','Brynhild','Beowulf','Ragnar','Sif','Leif','Gudrun','Skadi'],rook:['Heimdall','Tyr'],knight:['Thor','Freya'],bishop:['Frigg','Baldr'],queen:['Hel'],king:['Odin']};
  turn='olympus';selected=null;legal=[];skillMode=false;round=1;history=[];gameOver=false;lastMove=null;document.querySelector('#move-log').innerHTML='<li class="log-empty">Les dieux attendent votre premier coup.</li>';render();}
function inside(r,c){return r>=0&&r<8&&c>=0&&c<8}
function lineClear(r,c,nr,nc){const dr=Math.sign(nr-r),dc=Math.sign(nc-c);let y=r+dr,x=c+dc;while(y!==nr||x!==nc){if(grid[y][x])return false;y+=dr;x+=dc}return true}
function movesFor(r,c){const p=grid[r][c];if(!p)return[];const out=[];const add=(nr,nc)=>{if(!inside(nr,nc))return false;const target=grid[nr][nc];if(!target||target.team!==p.team)out.push({r:nr,c:nc,attack:!!target});return !target};const dir=p.team==='olympus'?-1:1;
 if(p.type==='pawn'){if(inside(r+dir,c)&&!grid[r+dir][c]){add(r+dir,c);const start=p.team==='olympus'?6:1;if(r===start&&!grid[r+2*dir][c])add(r+2*dir,c)}for(const dc of [-1,1])if(inside(r+dir,c+dc)&&grid[r+dir][c+dc]?.team!==p.team&&grid[r+dir][c+dc])add(r+dir,c+dc);}
 else if(p.type==='knight'){for(const[dr,dc]of [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]])add(r+dr,c+dc)}
 else{let dirs=[];if(['rook','queen','king'].includes(p.type))dirs.push([1,0],[-1,0],[0,1],[0,-1]);if(['bishop','queen','king'].includes(p.type))dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(const[dr,dc]of dirs){let nr=r+dr,nc=c+dc;while(inside(nr,nc)){const empty=add(nr,nc);if(p.type==='king'||!empty)break;nr+=dr;nc+=dc}}}
 return out}
function skillTargets(r,c){const p=grid[r]?.[c];if(!p||p.used)return[];const result=[];for(let nr=0;nr<8;nr++)for(let nc=0;nc<8;nc++){const t=grid[nr][nc];if(p.type==='pawn'){const d=p.team==='olympus'?-1:1;if(nc===c&&nr===r+2*d&&inside(r+d,c)&&!grid[r+d][c]&&!t)result.push({r:nr,c:nc})}
 else if(p.type==='rook'){if(t?.team===p.team&&(Math.abs(nr-r)<=1&&Math.abs(nc-c)<=1)&&(nr!==r||nc!==c)&&t.hp<t.maxHp)result.push({r:nr,c:nc})}
 else if(p.type==='knight'){if(t&&t.team!==p.team&&Math.max(Math.abs(nr-r),Math.abs(nc-c))<=2)result.push({r:nr,c:nc})}
 else if(p.type==='bishop'){const diag=Math.abs(nr-r)===Math.abs(nc-c);if(t?.team===p.team&&t.hp<t.maxHp&&(nr===r&&nc===c||diag&&lineClear(r,c,nr,nc)))result.push({r:nr,c:nc})}
 else if(p.type==='queen'){const aligned=nr===r||nc===c||Math.abs(nr-r)===Math.abs(nc-c);if(t&&t.team!==p.team&&aligned&&lineClear(r,c,nr,nc))result.push({r:nr,c:nc})}
 else if(p.type==='king'){if(t?.team===p.team&&t.hp<t.maxHp&&Math.max(Math.abs(nr-r),Math.abs(nc-c))<=1)result.push({r:nr,c:nc})}}
 return result}
function render(){boardEl.innerHTML='';for(let r=0;r<8;r++)for(let c=0;c<8;c++){const sq=document.createElement('button');sq.type='button';sq.className=`square ${(r+c)%2?'dark':'light'}`;sq.dataset.r=r;sq.dataset.c=c;sq.setAttribute('role','gridcell');const coord=document.createElement('span');coord.className='coord';coord.textContent=`${'abcdefgh'[c]}${8-r}`;sq.append(coord);const p=grid[r][c];if(p){const piece=document.createElement('div');piece.className=`piece ${teams[p.team].className}${p.used?' used':''}`;piece.title=`${p.name} · ${specs[p.type].title} · ${p.hp}/${p.maxHp} PV${p.used?' · pouvoir utilisé':''}`;piece.innerHTML=`<span class="piece-glyph">${specs[p.type].glyph}</span><span class="piece-name"></span><span class="piece-health"><i></i></span>`;piece.querySelector('.piece-name').textContent=p.name;const bar=piece.querySelector('.piece-health i');bar.style.width=`${Math.max(0,p.hp/p.maxHp*100)}%`;if(p.hp<=Math.ceil(p.maxHp/3))bar.classList.add('low');sq.append(piece)}if(selected&&selected.r===r&&selected.c===c)sq.classList.add('selected');if(legal.some(m=>m.r===r&&m.c===c))sq.classList.add(legal.find(m=>m.r===r&&m.c===c).attack?'attack-target':'move-target');if(skillMode&&selected&&skillTargets(selected.r,selected.c).some(t=>t.r===r&&t.c===c))sq.classList.add('skill-target');if(lastMove&&((lastMove.from.r===r&&lastMove.from.c===c)||(lastMove.to.r===r&&lastMove.to.c===c)))sq.classList.add('last-move');sq.setAttribute('aria-label',`${'abcdefgh'[c]}${8-r}${p?`, ${p.name}, ${p.hp} points de vie`:''}`);boardEl.append(sq)}
 document.querySelector('#rank-labels').innerHTML=Array.from({length:8},(_,i)=>`<span>${8-i}</span>`).join('');document.querySelector('#file-labels').innerHTML=Array.from('abcdefgh',f=>`<span>${f}</span>`).join('');document.querySelector('#turn-mark').textContent=teams[turn].emblem;document.querySelector('#turn-mark').classList.toggle('asgard',turn==='asgard');document.querySelector('#turn-label').textContent=gameOver?'PARTIE TERMINÉE':'À VOUS DE JOUER';document.querySelector('#turn-name').textContent=gameOver?`${teams[turn].name} triomphent`:`${teams[turn].name}`;document.querySelector('#round-number').textContent=String(round).padStart(2,'0');document.querySelector('#olympian-card').classList.toggle('active',turn==='olympus'&&!gameOver);document.querySelector('#asgardian-card').classList.toggle('active',turn==='asgard'&&!gameOver);document.querySelector('#olympian-status').textContent=turn==='olympus'&&!gameOver?'À L’AUBE':'DANS L’OMBRE';document.querySelector('#asgardian-status').textContent=turn==='asgard'&&!gameOver?'À L’AUBE':'DANS L’OMBRE';updateArmyStats();updateDetails();updateAbility();document.querySelector('#log-count').textContent=String(history.length+1).padStart(2,'0')}
function updateArmyStats(){for(const team of ['olympus','asgard']){let count=0,hp=0;grid.flat().forEach(p=>{if(p?.team===team){count++;hp+=p.hp}});document.querySelector(`#${team}-count`).textContent=count;document.querySelector(`#${team}-health`).textContent=hp}}
function updateDetails(){const empty=document.querySelector('#empty-selection'),details=document.querySelector('#piece-details'),p=selected&&grid[selected.r][selected.c];if(!p){empty.classList.remove('hidden');details.classList.add('hidden');return}empty.classList.add('hidden');details.classList.remove('hidden');details.innerHTML=`<span class="detail-glyph ${p.team==='asgard'?'asgard':''}">${specs[p.type].glyph}</span><div class="detail-text"><div class="detail-name"></div><div class="detail-title">${specs[p.type].title} · ${teams[p.team].name}</div><div class="detail-meter"><i></i></div></div><div class="detail-hp"><b>${p.hp}</b>/${p.maxHp}<br>PV</div>`;details.querySelector('.detail-name').textContent=p.name;details.querySelector('.detail-meter i').style.width=`${p.hp/p.maxHp*100}%`}
function updateAbility(){const button=document.querySelector('#ability-button'),label=document.querySelector('#ability-label'),copy=document.querySelector('#ability-copy'),p=selected&&grid[selected.r][selected.c];button.classList.toggle('armed',skillMode);if(!p){button.disabled=true;label.textContent='Choisissez un héros';copy.textContent='Chaque héros peut invoquer son pouvoir une fois par partie.';return}copy.textContent=specs[p.type].description;if(p.team!==turn||gameOver){button.disabled=true;label.textContent='Attendez votre tour';return}if(p.used&&!skillMode){button.disabled=true;label.textContent='Pouvoir déjà utilisé';return}button.disabled=false;label.textContent=skillMode?'Annuler le pouvoir':specs[p.type].skill}
function log(text,team=turn){if(history.length===0)document.querySelector('#move-log').innerHTML='';history.unshift({text,team});const li=document.createElement('li');li.className=team==='asgard'?'asgard-log':'';const num=document.createElement('span');num.className='log-turn';num.textContent=String(history.length).padStart(2,'0');const msg=document.createElement('span');msg.textContent=text;li.append(num,msg);document.querySelector('#move-log').prepend(li);document.querySelector('#log-count').textContent=String(history.length+1).padStart(2,'0')}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function endTurn(){skillMode=false;selected=null;legal=[];turn=turn==='olympus'?'asgard':'olympus';if(turn==='olympus')round++;render()}
function removeAt(r,c){const p=grid[r][c];grid[r][c]=null;return p}
function victory(team){gameOver=true;turn=team;toast(`${teams[team].name} remportent la bataille !`)}
function checkDeath(piece,r,c){if(piece.hp>0)return false;removeAt(r,c);log(`${piece.name} tombe au combat.` ,piece.team);if(piece.type==='king'){victory(piece.team==='olympus'?'asgard':'olympus');return true}return false}
function promote(piece,r){if(piece.type==='pawn'&&(r===0||r===7)){piece.type='queen';piece.maxHp=specs.queen.hp;piece.hp=Math.min(piece.maxHp,piece.hp+2);piece.used=false;toast(`${piece.name} s’élève au rang de déesse !`)}}
function normalMove(from,to){const p=grid[from.r][from.c],target=grid[to.r][to.c];lastMove={from,to};if(target){target.hp-=2;log(`${p.name} attaque ${target.name} : −2 PV.`);if(target.hp<=0){removeAt(to.r,to.c);grid[to.r][to.c]=p;removeAt(from.r,from.c);log(`${target.name} est vaincu.`,target.team);if(target.type==='king'){promote(p,to.r);victory(p.team);return}promote(p,to.r)}else{p.hp-=1;log(`${target.name} résiste ; ${p.name} subit −1 PV.`);if(p.hp<=0){checkDeath(p,from.r,from.c);if(gameOver)return}}}else{grid[to.r][to.c]=p;removeAt(from.r,from.c);promote(p,to.r);log(`${p.name} rejoint la case ${'abcdefgh'[to.c]}${8-to.r}.`)}if(!gameOver)endTurn()}
function applySkill(from,to){const p=grid[from.r][from.c],target=grid[to.r][to.c];if(!p||!target)return;let message='';if(p.type==='pawn'){grid[to.r][to.c]=p;removeAt(from.r,from.c);message=`${p.name} bondit de deux cases !`;promote(p,to.r)}else if(p.type==='rook'||p.type==='bishop'){const amount=2,healed=Math.min(amount,target.maxHp-target.hp);target.hp+=healed;message=`${p.name} restaure ${healed} PV à ${target.name}.`}else if(p.type==='king'){const healed=Math.min(3,target.maxHp-target.hp);target.hp+=healed;message=`${p.name} invoque l’Égide : +${healed} PV pour ${target.name}.`}else{const damage=p.type==='knight'?3:3;target.hp-=damage;message=`${p.name} frappe ${target.name} : −${damage} PV !`;if(target.hp<=0){removeAt(to.r,to.c);if(target.type==='king'){log(`${target.name} est vaincu.`,target.team);p.used=true;log(message);victory(p.team);return}message+=` ${target.name} tombe.`}}p.used=true;lastMove={from,to};log(message);if(target.hp<=0&&target.type==='king'){victory(p.team);return}endTurn()}
boardEl.addEventListener('click',e=>{const cell=e.target.closest('.square');if(!cell||gameOver)return;const r=Number(cell.dataset.r),c=Number(cell.dataset.c),p=grid[r][c];if(skillMode&&selected){const targets=skillTargets(selected.r,selected.c);if(targets.some(t=>t.r===r&&t.c===c)){applySkill(selected,{r,c});return}if(p?.team===turn){selected={r,c};legal=[];skillMode=false;render();toast('Pouvoir annulé. Choisissez une autre pièce.');return}toast('Cette cible ne peut pas être touchée par ce pouvoir.');return}if(selected&&legal.some(m=>m.r===r&&m.c===c)){normalMove(selected,{r,c});return}if(p?.team===turn){selected={r,c};legal=movesFor(r,c);render();return}if(selected){toast('Case inaccessible.');selected=null;legal=[];render()}});
document.querySelector('#ability-button').addEventListener('click',()=>{if(skillMode){skillMode=false;render();return}const p=selected&&grid[selected.r][selected.c];if(!p||p.used||p.team!==turn)return;skillMode=true;legal=[];render();if(skillTargets(selected.r,selected.c).length===0){skillMode=false;render();toast('Aucune cible valide pour ce pouvoir.');return}toast('Choisissez une case illuminée pour invoquer le pouvoir.')});
document.querySelector('#rules-open').addEventListener('click',()=>document.querySelector('#rules-dialog').showModal());document.querySelector('#rules-close').addEventListener('click',()=>document.querySelector('#rules-dialog').close());document.querySelector('#new-game').addEventListener('click',()=>document.querySelector('#new-dialog').showModal());document.querySelector('#cancel-new').addEventListener('click',()=>document.querySelector('#new-dialog').close());document.querySelector('#confirm-new').addEventListener('click',()=>{document.querySelector('#new-dialog').close();setup();toast('Les deux armées sont prêtes. À vous de jouer !')});
